//! Unit and hostile-input tests for the portable MP3 backend. They use only
//! generated bytes: no encoder, no external files.
use super::mp3_l3::{Decoder, Header, Pcm, Version, GRANULE};
use super::mp3_math::{cos_pi_frac, sin_pi_frac, tables, QUARTER_BIAS};
use super::{quantize, Mp3Error, Mp3Stream};
use std::io::Write;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12; self.0 ^= self.0 << 25; self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }
    fn below(&mut self, n: u32) -> u32 { (self.next() >> 33) as u32 % n.max(1) }
}

static NEXT: AtomicU64 = AtomicU64::new(0);
struct TempFile(PathBuf);
impl TempFile {
    fn new(bytes: &[u8]) -> TempFile {
        let path = std::env::temp_dir().join(format!("pn-mp3-test-{}-{}.mp3", std::process::id(), NEXT.fetch_add(1, Ordering::Relaxed)));
        std::fs::File::create(&path).unwrap().write_all(bytes).unwrap();
        TempFile(path)
    }
    fn open(&self) -> Result<Mp3Stream, Mp3Error> { Mp3Stream::open(std::fs::File::open(&self.0).unwrap()) }
}
impl Drop for TempFile { fn drop(&mut self) { let _ = std::fs::remove_file(&self.0); } }

/// A silent MPEG-1 Layer III frame (128 kbps, 44.1 kHz): the all-zero side
/// information decodes as two empty granules.
fn silent_frame(mono: bool) -> Vec<u8> {
    let mut frame = vec![0u8; 417];
    frame[..4].copy_from_slice(&[0xff, 0xfb, 0x90, if mono { 0xc0 } else { 0x00 }]);
    frame
}

fn read_all(stream: &mut Mp3Stream) -> Result<Vec<f32>, Mp3Error> {
    let (mut l, mut r) = (vec![0f32; 512], vec![0f32; 512]);
    let mut out = Vec::new();
    loop {
        let n = stream.read_planar(&mut l, &mut r)?;
        if n == 0 { return Ok(out); }
        out.extend_from_slice(&l[..n]);
    }
}

#[test]
fn math_tables_match_closed_forms() {
    assert!((cos_pi_frac(1, 3) - 0.5).abs() < 1e-15);
    assert!((sin_pi_frac(1, 6) - 0.5).abs() < 1e-15);
    assert_eq!(cos_pi_frac(1, 2), 0.0f64.max(cos_pi_frac(1, 2)).min(1e-15));
    assert!((cos_pi_frac(72, 72) + 1.0).abs() < 1e-15);
    let t = tables();
    assert!((t.pow43[8] - 16.0).abs() < 1e-12);
    assert!((t.pow43[1000] / 10_000.0 - 1.0).abs() < 1e-12);
    assert_eq!(t.quarter[(QUARTER_BIAS + 4) as usize], 2.0);
    assert_eq!(t.quarter[(QUARTER_BIAS - 8) as usize], 0.25);
    assert_eq!(t.quarter[(QUARTER_BIAS + 2) as usize].to_bits(), 2.0f64.sqrt().to_bits());
    // The folded IMDCT basis agrees with libm to rounding error (libm is used only here, in a test).
    let pi = std::f64::consts::PI;
    for (k, i) in [(0usize, 0usize), (3, 17), (17, 35), (9, 20)] {
        let window = (pi / 36.0 * (i as f64 + 0.5)).sin();
        let expected = window * (pi / 72.0 * ((2 * i + 19) * (2 * k + 1)) as f64).cos();
        assert!((t.imdct36[0][k * 36 + i] - expected).abs() < 1e-14, "imdct36[{k}][{i}]");
    }
    for (k, i) in [(0usize, 0usize), (5, 11), (2, 7)] {
        let window = (pi / 12.0 * (i as f64 + 0.5)).sin();
        let expected = window * (pi / 24.0 * ((2 * i + 7) * (2 * k + 1)) as f64).cos();
        assert!((t.imdct12[k * 12 + i] - expected).abs() < 1e-14, "imdct12[{k}][{i}]");
    }
}

#[test]
fn huffman_trees_are_complete_prefix_codes() {
    for (n, tree) in tables().big_trees.iter().enumerate() {
        let Some(tree) = tree else { continue };
        for (i, node) in tree.nodes.iter().enumerate() {
            assert!(node[0] != 0 && node[1] != 0, "table {n} node {i} has a missing branch");
        }
    }
    for tree in &tables().count1_trees {
        assert!(tree.nodes.iter().all(|node| node[0] != 0 && node[1] != 0));
    }
}

#[test]
fn quantizer_rounds_to_the_16_bit_grid_and_saturates() {
    assert_eq!(quantize(0.0), 0.0);
    assert_eq!(quantize(1.0), 32767.0 / 32768.0);
    assert_eq!(quantize(-1.0), -1.0);
    assert_eq!(quantize(40.0), 32767.0 / 32768.0);
    assert_eq!(quantize(-40.0), -1.0);
    assert_eq!(quantize(0.4 / 32768.0), 0.0);
    assert_eq!(quantize(0.6 / 32768.0), 1.0 / 32768.0);
    assert_eq!(quantize(f64::NAN), 0.0);
    assert_eq!(quantize(f64::INFINITY), 32767.0 / 32768.0);
}

#[test]
fn silent_stream_has_apple_alignment_without_a_tag() {
    let mut data = Vec::new();
    for _ in 0..5 { data.extend(silent_frame(false)); }
    let file = TempFile::new(&data);
    let mut stream = file.open().unwrap();
    let info = stream.info();
    assert_eq!((info.sample_rate, info.channels, info.frames_per_packet), (44_100, 2, 1152));
    assert_eq!(info.length_frames, 5 * 1152);
    assert_eq!(info.bitrate, 128_000);
    let samples = read_all(&mut stream).unwrap();
    assert_eq!(samples.len(), 5 * 1152);
    assert!(samples.iter().all(|&v| v == 0.0));
}

#[test]
fn partial_last_frame_and_trailing_tags_are_ignored() {
    let mut data = Vec::new();
    for _ in 0..4 { data.extend(silent_frame(true)); }
    data.extend(&silent_frame(true)[..200]);
    let file = TempFile::new(&data);
    assert_eq!(file.open().unwrap().info().length_frames, 4 * 1152);
    let mut with_v1 = Vec::new();
    for _ in 0..4 { with_v1.extend(silent_frame(false)); }
    let mut tag = vec![0u8; 128];
    tag[..3].copy_from_slice(b"TAG");
    with_v1.extend(tag);
    assert_eq!(TempFile::new(&with_v1).open().unwrap().info().length_frames, 4 * 1152);
    // Leading ID3v2 data and zero padding do not matter either.
    let mut id3 = b"ID3\x03\x00\x00\x00\x00\x00\x20".to_vec();
    id3.extend(vec![0u8; 32]);
    id3.extend(vec![0u8; 77]);
    for _ in 0..3 { id3.extend(silent_frame(false)); }
    assert_eq!(TempFile::new(&id3).open().unwrap().info().length_frames, 3 * 1152);
}

#[test]
fn mono_streams_duplicate_into_the_second_plane() {
    let mut data = Vec::new();
    for _ in 0..3 { data.extend(silent_frame(true)); }
    let file = TempFile::new(&data);
    let mut stream = file.open().unwrap();
    assert_eq!(stream.info().channels, 1);
    let (mut l, mut r) = (vec![9f32; 100], vec![7f32; 100]);
    assert_eq!(stream.read_planar(&mut l, &mut r).unwrap(), 100);
    assert!(l.iter().all(|&v| v == 0.0) && r.iter().all(|&v| v == 0.0));
}

/// A LAME-style Info frame: header, zero side info, tag at offset 36, flags 15.
fn info_frame(frames: u32, bytes: u32, delay: u32, padding: u32, ident: &[u8; 4], crc_ok: bool) -> Vec<u8> {
    let mut f = silent_frame(false);
    f[36..40].copy_from_slice(b"Info");
    f[40..44].copy_from_slice(&15u32.to_be_bytes());
    f[44..48].copy_from_slice(&frames.to_be_bytes());
    f[48..52].copy_from_slice(&bytes.to_be_bytes());
    let ext = 156;
    f[ext..ext + 4].copy_from_slice(ident);
    let packed = (delay << 12) | padding;
    f[ext + 21..ext + 24].copy_from_slice(&packed.to_be_bytes()[1..]);
    let crc = super::lame_crc(&f[..ext + 34]);
    let crc = if crc_ok { crc } else { !crc };
    f[ext + 34..ext + 36].copy_from_slice(&crc.to_be_bytes());
    f
}

#[test]
fn lame_info_header_sets_length_and_start_trim() {
    // 30 audio frames; the Info byte count is the file size including the Info frame.
    let mut data = info_frame(30, 31 * 417, 576, 1242, b"LAME", true);
    for _ in 0..30 { data.extend(silent_frame(false)); }
    let file = TempFile::new(&data);
    let mut stream = file.open().unwrap();
    let info = stream.info();
    // Packet estimate: ceil((bytes - frame) * 8 / bitrate * rate / spf), gapless fields from the tag.
    let packets = (((30 * 417) as f64 * 8.0 / 128_000.0) * (44_100.0 / 1152.0)).ceil() as i64;
    assert_eq!(info.length_frames, packets * 1152 - 576 - 1242);
    assert_eq!(info.bitrate, 128_000);
    let samples = read_all(&mut stream).unwrap();
    // Decoded packets are limited by the file; the output ends at the shorter of the two.
    assert_eq!(samples.len() as i64, (30 * 1152 - 576).min(info.length_frames));
}

#[test]
fn foreign_info_header_needs_a_valid_crc_for_gapless_fields() {
    for (crc_ok, expected_delay) in [(true, 576u64), (false, 0)] {
        let mut data = info_frame(30, 31 * 417, 576, 1242, b"Lavc", crc_ok);
        for _ in 0..30 { data.extend(silent_frame(false)); }
        let file = TempFile::new(&data);
        let info = file.open().unwrap().info();
        assert_eq!(info.length_frames as u64, 30 * 1152 - expected_delay - if crc_ok { 1242 } else { 0 });
    }
}

#[test]
fn unsupported_layouts_are_refused_with_typed_errors() {
    // Layer II frame, 128 kbit/s at 44.1 kHz: 144 * 128000 / 44100 = 417 bytes.
    let mut layer2 = vec![0u8; 417];
    layer2[..4].copy_from_slice(&[0xff, 0xfd, 0x80, 0x00]);
    let two = vec![layer2.clone(), layer2.clone(), layer2].concat();
    assert!(matches!(TempFile::new(&two).open(), Err(Mp3Error::Unsupported(_))));
    // Free-format header (bitrate index 0).
    let mut free = vec![0u8; 417];
    free[..4].copy_from_slice(&[0xff, 0xfb, 0x00, 0x00]);
    let three = vec![free.clone(), free.clone(), free].concat();
    assert!(matches!(TempFile::new(&three).open(), Err(Mp3Error::Unsupported(_))));
    // Not MP3 at all.
    assert!(matches!(TempFile::new(b"RIFFnope").open(), Err(Mp3Error::NotMp3)));
    assert!(matches!(TempFile::new(&[0u8; 5000]).open(), Err(Mp3Error::NotMp3)));
    // An ID3v2 tag past the end, a lone truncated frame and a stream with no frames have nothing to
    // confirm: the caller keeps its own classification.
    assert!(matches!(TempFile::new(b"ID3\x03\x00\x00\x00\x00\x7f\x7f").open(), Err(Mp3Error::NotMp3)));
    assert!(matches!(TempFile::new(&silent_frame(false)[..100]).open(), Err(Mp3Error::NotMp3)));
    assert!(matches!(TempFile::new(b"ID3\x03\x00\x00\x00\x00\x00\x00").open(), Err(Mp3Error::NotMp3)));
}

#[test]
fn damaged_granule_is_an_error_at_the_first_read() {
    let mut frame = silent_frame(false);
    // main_data_begin = 0, granule 0 channel 0 part2_3_length = 4095.
    frame[4..8].copy_from_slice(&[0x00, 0x00, 0x0f, 0xff]);
    let data = vec![frame.clone(), frame.clone(), frame].concat();
    let file = TempFile::new(&data);
    let mut stream = file.open().unwrap();
    let (mut l, mut r) = (vec![0f32; 16], vec![0f32; 16]);
    assert!(matches!(stream.read_planar(&mut l, &mut r), Err(Mp3Error::Corrupt("MP3 frame data is damaged"))));
}

#[test]
fn hostile_frames_never_panic_and_stay_finite() {
    let mut rng = Rng(0x1234_5678_9abc_def1);
    let mut decoder = Decoder::new();
    let mut pcm = Pcm::new();
    let (mut ok, mut damaged) = (0usize, 0usize);
    for round in 0..1_500u32 {
        // A valid header of any version / rate / mode / bitrate with a random or mostly-zero body.
        let version_bits = [3u32, 2, 0][rng.below(3) as usize];
        let word = 0xffe0_0000 | (version_bits << 19) | (1 << 17) | (1 << 16) | (rng.below(15) << 12) | (rng.below(3) << 10)
            | (rng.below(4) << 6) | (rng.below(4) << 4);
        let Some(header) = Header::parse(word) else { continue };
        let size = header.frame_bytes();
        if size < 8 { continue; }
        let mut body = vec![0u8; size - 4];
        let density = [1u32, 4, 64, 256][rng.below(4) as usize];
        for byte in body.iter_mut() { if rng.below(256) < density { *byte = rng.below(256) as u8; } }
        if round % 7 == 0 { for byte in body.iter_mut().take(40) { *byte = rng.below(256) as u8; } }
        match decoder.decode_frame(&header, &body, &mut pcm) {
            Ok(status) => {
                if status.damaged { damaged += 1 } else { ok += 1 }
                for ch in 0..header.channels() {
                    for &v in &pcm.data[ch][..status.granules * GRANULE] { assert!(v.is_finite() && v.abs() < 1e12, "unbounded sample {v}"); }
                }
            }
            Err(_) => {}
        }
    }
    assert!(ok > 100 && damaged > 100, "expected a mix of decodable and damaged frames ({ok}/{damaged})");
    let _ = Version::V1;
}

#[test]
fn hostile_files_never_panic() {
    let mut rng = Rng(0x0fed_cba9_8765_4321);
    let mut base = info_frame(10, 11 * 417, 576, 1242, b"LAME", true);
    for i in 0..10 {
        let mut f = silent_frame(i % 2 == 0);
        if i % 2 == 0 { f = silent_frame(false); }
        for byte in f.iter_mut().skip(40) { if rng.below(4) == 0 { *byte = rng.below(256) as u8; } }
        base.extend(f);
    }
    for case in 0..400u32 {
        let mut data = base.clone();
        match case % 5 {
            0 => { let n = rng.below(data.len() as u32) as usize; data.truncate(n); }
            1 => { for _ in 0..1 + rng.below(30) { let i = rng.below(data.len() as u32) as usize; data[i] = rng.below(256) as u8; } }
            2 => { let at = rng.below(data.len() as u32) as usize; let junk: Vec<u8> = (0..rng.below(2000)).map(|_| rng.below(256) as u8).collect(); data.splice(at..at, junk); }
            3 => { data = (0..rng.below(6000)).map(|_| rng.below(256) as u8).collect(); }
            _ => { let at = rng.below(data.len() as u32) as usize; data.drain(at..(at + rng.below(900) as usize).min(data.len())); }
        }
        let file = TempFile::new(&data);
        let Ok(mut stream) = file.open() else { continue };
        let _ = stream.info();
        let (mut l, mut r) = (vec![0f32; 700], vec![0f32; 700]);
        let mut total = 0u64;
        loop {
            match stream.read_planar(&mut l, &mut r) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    total += n as u64;
                    assert!(l[..n].iter().chain(&r[..n]).all(|v| v.is_finite() && v.abs() <= 1.0));
                }
            }
        }
        assert!(total <= stream.info().length_frames.max(0) as u64 + 2 * 1152 + 529);
    }
}

#[test]
fn bogus_header_values_cannot_allocate_or_loop_unboundedly() {
    // Huge Xing counts, byte counts and delay fields must be refused or bounded, never trusted.
    for (frames, bytes, delay, padding) in [(u32::MAX, u32::MAX, 4095u32, 4095u32), (1, 1, 0, 0), (0, 0, 0, 0), (u32::MAX, 20_000, 0, 0)] {
        let mut data = info_frame(frames, bytes, delay, padding, b"LAME", true);
        for _ in 0..6 { data.extend(silent_frame(false)); }
        if let Ok(mut stream) = TempFile::new(&data).open() {
            let (mut l, mut r) = (vec![0f32; 4096], vec![0f32; 4096]);
            let mut total = 0u64;
            while let Ok(n) = stream.read_planar(&mut l, &mut r) {
                if n == 0 { break; }
                total += n as u64;
                assert!(total < 20_000, "output is bounded by the decoded packets");
            }
        }
    }
}

/// A VBRI frame as AudioToolbox reads it: marker at byte 36, stream bytes at 46, frame count at 50
/// (the count includes this frame); version, delay and quality are ignored.
fn vbri_frame(bytes: u32, frames: u32) -> Vec<u8> {
    let mut frame = silent_frame(false);
    frame[36..40].copy_from_slice(b"VBRI");
    frame[40..46].copy_from_slice(&[0, 2, 0x04, 0x51, 0, 75]);
    frame[46..50].copy_from_slice(&bytes.to_be_bytes());
    frame[50..54].copy_from_slice(&frames.to_be_bytes());
    frame
}

#[test]
fn vbri_header_sets_packets_and_bitrate_from_the_byte_and_frame_fields() {
    // Values recorded from AudioToolbox for 13 audio frames behind a 417-byte VBRI frame.
    for (bytes, frames, length, bitrate) in [
        (5850u32, 14u32, 14976i64, 127_988u32), (9999, 20, 21888, 154_446), (5850, 13, 13824, 138_654), (5850, 2, 1152, 1_663_856),
        (5850, 100, 114_048, 16_806), (5850, 0, 14976, 128_000), (5850, 1, 14976, 128_000), (0, 14, 14976, 128_000),
        (100, 14, 14976, 2355), (417, 14, 14976, 9823), (u32::MAX, 14, 14976, u32::MAX), (5850, u32::MAX, 4_947_802_322_688, 128_000),
    ] {
        let mut data = vbri_frame(bytes, frames);
        for _ in 0..13 { data.extend(silent_frame(false)); }
        let file = TempFile::new(&data);
        let mut stream = file.open().unwrap_or_else(|e| panic!("bytes {bytes} frames {frames}: {e:?}"));
        let info = stream.info();
        assert_eq!((info.length_frames, info.bitrate), (length, bitrate), "bytes {bytes} frames {frames}");
        // The frames delivered never depend on the header: every scanned frame is decoded.
        assert_eq!(read_all(&mut stream).unwrap().len(), 13 * 1152, "bytes {bytes} frames {frames}");
    }
}

#[test]
fn vbri_is_recognised_in_every_mpeg_layout() {
    // MPEG-2 22.05 kHz stereo, 128 kbit/s: 13 frames of 576 samples behind the VBRI frame.
    let mut frame = vec![0u8; 417];
    frame[..4].copy_from_slice(&[0xff, 0xf3, 0xc0, 0x00]);
    let mut data = frame.clone();
    data[36..40].copy_from_slice(b"VBRI");
    data[46..50].copy_from_slice(&5_000u32.to_be_bytes());
    data[50..54].copy_from_slice(&6u32.to_be_bytes());
    for _ in 0..13 { data.extend(&frame); }
    let info = TempFile::new(&data).open().unwrap().info();
    assert_eq!(info.length_frames, 5 * 576);
    assert_eq!(info.bitrate, ((5000 - 417) as f64 * 8.0 / (5.0 * 576.0 / 22050.0)) as u32);
}

#[test]
fn truncated_final_frame_is_accepted_at_every_byte_offset() {
    let mut full = Vec::new();
    for _ in 0..6 { full.extend(silent_frame(false)); }
    let last = full.len() - 417;
    for cut in 0..417 {
        let file = TempFile::new(&full[..last + cut]);
        let mut stream = file.open().unwrap_or_else(|e| panic!("cut {cut}: {e:?}"));
        assert_eq!(stream.info().length_frames, 5 * 1152, "cut {cut}");
        assert_eq!(read_all(&mut stream).unwrap().len(), 5 * 1152, "cut {cut}");
    }
    // A header cut short that does not belong to the stream is still refused.
    let mut other = full[..last].to_vec();
    other.extend([0xff, 0xe2]);
    assert!(TempFile::new(&other).open().is_err());
}

#[test]
fn a_frame_rewritten_after_open_is_an_error_not_a_panic() {
    use std::io::{Seek, SeekFrom};
    // More than one read buffer of frames, so a late frame is read from the file after it was rewritten.
    let mut data = Vec::new();
    for _ in 0..200 { data.extend(silent_frame(false)); }
    for (name, header) in [("free-format", [0xff, 0xfb, 0x00, 0x00]), ("other stream", [0xff, 0xfb, 0x90, 0xc0]), ("not a header", [0, 0, 0, 0])] {
        let file = TempFile::new(&data);
        let mut stream = file.open().unwrap();
        let mut out = std::fs::OpenOptions::new().write(true).open(&file.0).unwrap();
        out.seek(SeekFrom::Start(190 * 417)).unwrap();
        out.write_all(&header).unwrap();
        drop(out);
        match read_all(&mut stream) {
            Err(Mp3Error::Corrupt(_)) => {}
            other => panic!("{name}: expected a Corrupt error, got {:?}", other.map(|v| v.len())),
        }
    }
}

#[test]
fn only_a_confirmed_stream_is_an_mp3() {
    let frames = |n: usize| (0..n).flat_map(|_| silent_frame(false)).collect::<Vec<u8>>();
    // Junk without anything frame-like before the frames is skipped.
    let mut junk = vec![0x41u8; 3000];
    junk.extend(frames(5));
    assert_eq!(TempFile::new(&junk).open().unwrap().info().length_frames, 5 * 1152);
    // A junk prefix with a header-like pattern in it is ambiguous, not guessed.
    let mut ambiguous = vec![0x41u8; 100];
    ambiguous.extend([0xff, 0xfb, 0x90, 0x00]);
    ambiguous.extend(vec![0x41u8; 50]);
    ambiguous.extend(frames(5));
    assert!(matches!(TempFile::new(&ambiguous).open(), Err(Mp3Error::Unsupported("ambiguous data before the first MP3 frame"))));
    // A single frame that ends the file is a stream; the same frame followed by anything else is not.
    assert!(TempFile::new(&frames(1)).open().is_ok());
    let mut one_then_noise = frames(1);
    one_then_noise.extend(vec![0x55u8; 1000]);
    assert!(matches!(TempFile::new(&one_then_noise).open(), Err(Mp3Error::NotMp3)));
    // Three consecutive frames confirm the stream; trailing bytes that cannot start a frame are tolerated.
    let mut three_then_noise = frames(3);
    three_then_noise.extend(vec![0x55u8; 1000]);
    assert!(TempFile::new(&three_then_noise).open().is_ok());
    // Frame-like bytes in random data never confirm anything. The injected headers are 211 bytes apart,
    // so no run of them can have the 417-byte spacing of consecutive frames.
    let mut rng = Rng(0x5eed_0001);
    for round in 0..200 {
        let mut data: Vec<u8> = (0..2000 + rng.below(6000)).map(|_| rng.below(256) as u8).collect();
        let first = rng.below(200) as usize;
        let tail = data.len() - 1000;
        for at in (first..tail).step_by(211) {
            data[at..at + 4].copy_from_slice(&[0xff, 0xfb, 0x90, 0x00]);
        }
        // No frame can end the file: a lone frame ending within three bytes of its end would be a stream.
        for byte in &mut data[tail..] { if *byte == 0xff { *byte = 0xfe; } }
        let outcome = TempFile::new(&data).open();
        assert!(matches!(outcome, Err(Mp3Error::NotMp3)), "round {round}: {:?}", outcome.map(|_| ()));
    }
}
